#!/usr/bin/env python3
"""Writes string_literal_pending_test.obs, beside this file: its calls and literals are too long to type.

    python3 gen_string_literal_pending_test.py [out.obs]

Change a shape here and run it; the test is committed as written.
"""
import os
import sys

# the helper's Ints: with the String[] it takes 32 parameters
ARGS = 31
# STRING_LITERAL_STACK_MAX (core/compiler/context.h), for the header's text only
STACK_MAX = 6

HEAD = """#~
# A String array literal as the innermost argument of nested calls.
#
# GENERATED by gen_string_literal_pending_test.py (the calls are long): change a
# shape there, not a call here.
#
# The arguments of a call wait on the operand stack while the later ones are
# evaluated: in 'Pass(1, .., 31, Pass(1, .., 31, <literal>))' the inner literal is
# built on top of 62 Ints. A method has room for 1,000 words there, and the loader
# refuses one that holds more. A String literal of up to 512 elements was built on
# that stack too, every element pushed before one trap copied them, so sixteen
# levels of a helper that takes 31 Ints and a String[] (496 words waiting) around a
# literal of 512 strings compiled and then would not load:
#
#   >>> Invalid bytecode: ...:Deep496Lit512:, instruction 4014: the operand stack
#   grows to 1001 words past the arguments, more than a call's room <<<
#
# A literal of more than @MAX@ strings is now built an element at a time in a hidden
# local whatever is waiting under it, so it adds three words, not one for each
# string. Each function below returns its literal through the calls; every element
# is compared with the text its position spells, and every Int of every level is
# summed by the callee, so a waiting operand that was overwritten shows as well:
#
@SHAPES@
#
# What waits on the stack is still bounded: thirty-three such levels with no
# literal at all (1,023 Ints) need more than a call has, and obc says so at the
# expression's line where the loader used to refuse the program
# (check_stack_depth.py).
~#

class StringLiteralPendingTest {
  @sum : static : Int;
  @failed : static : Bool;

  function : Fail(what : String) ~ Nil {
    @failed := true;
    "  FAIL: {$what}"->PrintLine();
  }

  function : Pass(@PARAMS@, a : String[]) ~ String[] {
    @sum += @TOTAL@;
    return a;
  }

  # the literal's elements are prefix + their index; the levels' Ints add up to 'sum'
  function : Check(name : String, a : String[], prefix : String, size : Int, sum : Int) ~ Nil {
    if(a = Nil | a->Size() <> size) {
      Fail("{$name}: not {$size} elements");
      return;
    };
    wrong := 0;
    each(i : a) {
      e := String->New(prefix);
      e += i;
      if(a[i] = Nil | <>a[i]->Equals(e)) {
        wrong += 1;
      };
    };
    if(wrong <> 0) {
      Fail("{$name}: {$wrong} elements are not where they were written");
    };
    if(@sum <> sum) {
      got := @sum;
      Fail("{$name}: the levels' arguments add up to {$got}, not {$sum}");
    };
  }
"""

TAIL = """
    if(@failed) {
      "FAIL: String literals under waiting operands"->PrintLine();
      Runtime->Exit(1);
    };
    "PASS: String literals under waiting operands"->PrintLine();
  }
}
"""

# (levels, strings, why)
SHAPES = [
    (16, 512, "the case reported: 496 words wait, 512 strings"),
    (16, 100, "496 wait, 100 strings"),
    (20, 400, "620 wait, 400 strings: 1,022 words the old way, inside the stack's 1,024 and past the verifier's 1,000"),
    (25, 300, "775 wait, 300 strings"),
    (31, 512, "961 wait, 512 strings"),
    (31, 20, "961 wait, 20 strings"),
    (32, 40, "992 wait, the most this helper leaves under the limit, 40 strings"),
    (1, 600, "31 wait, 600 strings (already built an element at a time)"),
]


def literal(prefix, n, per=12, indent="      "):
    items = ['"%s%d"' % (prefix, i) for i in range(n)]
    rows = [", ".join(items[i:i + per]) for i in range(0, n, per)]
    return "[\n" + indent + (",\n" + indent).join(rows) + "]"


def nested(levels, inner):
    """Pass(<level 0's Ints>, Pass(<level 1's Ints>, ... inner)) and what the Ints add up to."""
    total = 0
    opened = ""
    for level in range(levels):
        values = [level * 100 + i for i in range(ARGS)]
        total += sum(values)
        opened += "Pass(" + ", ".join(str(v) for v in values) + ",\n      "
    return opened + inner + ")" * levels, total


def main():
    out = sys.argv[1] if len(sys.argv) > 1 else os.path.join(os.path.dirname(os.path.abspath(__file__)), "string_literal_pending_test.obs")
    params = ", ".join("p%d : Int" % i for i in range(ARGS))
    total = " + ".join("p%d" % i for i in range(ARGS))
    shapes = "\n".join("#   %-16s %s" % ("Deep%dLit%d" % (levels * ARGS, strings), why) for levels, strings, why in SHAPES)
    text = HEAD.replace("@MAX@", str(STACK_MAX)).replace("@SHAPES@", shapes).replace("@PARAMS@", params).replace("@TOTAL@", total)
    calls = ""
    for k, (levels, strings, why) in enumerate(SHAPES):
        prefix = "abcdefghij"[k]
        body, want = nested(levels, literal(prefix, strings))
        name = "Deep%dLit%d" % (levels * ARGS, strings)
        text += "\n  # %s\n  function : %s() ~ String[] {\n    return %s;\n  }\n" % (why, name, body)
        calls += ('    @sum := 0;\n    Check("%s", %s(), "%s", %d, %d);\n' % (name, name, prefix, strings, want))
    text += "\n  function : Main(args : String[]) ~ Nil {\n    @failed := false;\n" + calls + TAIL
    with open(out, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)


if __name__ == "__main__":
    main()
